//! The engine's Slang decode (`learned.slang` `learned_decode`) reproduces P2's PyTorch
//! decode (`learned_impact.outcome.decode`, the deployed rule) on fixed inputs, within fp32
//! tolerance, with identical break sets: P2's exported parity calls and variants that
//! exercise every branch (energy bound on a free call, an anchored call, a call made
//! non-free by gravity, extra breaks), decoded as one batch. The fixture is generated by
//! `learned-impact/scripts/p3_decode_fixture.py` and committed.

use stress_gpu::gpu::Gpu;
use stress_gpu::learned::{CallIn, Decode, DecodeConfig, NodeIn, CALL_FREE, DEC_BOUND_ACTIVE, DEC_BOUND_INFEASIBLE, DEC_NONFINITE};

fn f(v: &serde_json::Value) -> Vec<f64> {
    v.as_array().expect("array").iter().map(|x| x.as_f64().expect("number")).collect()
}

fn i(v: &serde_json::Value) -> Vec<i64> {
    v.as_array().expect("array").iter().map(|x| x.as_i64().expect("integer")).collect()
}

fn nodes(part: &serde_json::Value, chunks: bool) -> Vec<NodeIn> {
    let (m, inr, q, p, v, w, o) = (f(&part["mass"]), f(&part["inertia"]), f(&part["q"]), f(&part["pos"]), f(&part["v"]), f(&part["w"]), f(&part["out"]));
    let anch = if chunks { i(&part["anchored"]) } else { vec![0; m.len()] };
    let t3 = |a: &[f64], k: usize| [a[3 * k] as f32, a[3 * k + 1] as f32, a[3 * k + 2] as f32];
    (0..m.len())
        .map(|k| NodeIn {
            pos: t3(&p, k),
            mass: m[k] as f32,
            // The fixture's quaternions are w-first.
            q: [q[4 * k + 1] as f32, q[4 * k + 2] as f32, q[4 * k + 3] as f32, q[4 * k] as f32],
            inertia: t3(&inr, k),
            anchored: anch[k] != 0,
            v: t3(&v, k),
            w: t3(&w, k),
            out: std::array::from_fn(|c| o[12 * k + c] as f32),
        })
        .collect()
}

#[test]
fn slang_decode_matches_pytorch() {
    let text = std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/learned_decode.json")).expect("fixture");
    let doc: serde_json::Value = serde_json::from_str(&text).expect("json");
    let cfg = DecodeConfig { tau: doc["decode"]["tau"].as_f64().unwrap(), energy_tolerance: doc["decode"]["energy_tolerance"].as_f64().unwrap() };
    let keys = ["L", "m", "v", "c", "f_t", "E", "GA", "dt", "E_in"];
    let mut calls = Vec::new();
    for c in doc["calls"].as_array().unwrap() {
        let mut n = nodes(&c["chunks"], true);
        let chunks = n.len();
        n.extend(nodes(&c["impactors"], false));
        let b = &c["bonds"];
        let (d0, lq, dd, bin) = (f(&b["damage0"]), f(&b["log_q"]), f(&b["ddamage"]), i(&b["bin"]));
        let g = f(&c["gravity"]);
        calls.push(CallIn {
            scales: std::array::from_fn(|k| c["scales"][keys[k]].as_f64().unwrap() as f32),
            gravity: [g[0] as f32, g[1] as f32, g[2] as f32],
            flags: if c["free"].as_bool().unwrap() { CALL_FREE } else { 0 },
            chunks,
            nodes: n,
            bonds: (0..d0.len()).map(|k| (d0[k] as f32, lq[k] as f32, dd[k] as f32, bin[k] as u32)).collect(),
        });
    }
    let gpu = Gpu::new().expect("GPU");
    let got = Decode::new(&gpu).run(&gpu, &cfg, &calls);
    for (g, (c, (nodes_out, bonds_out, flags))) in doc["calls"].as_array().unwrap().iter().zip(&got).enumerate() {
        let e = &c["expected"];
        assert_eq!(flags & DEC_NONFINITE, 0, "call {g}: non-finite");
        assert_eq!(flags & DEC_BOUND_ACTIVE != 0, e["energy_bound_active"].as_bool().unwrap(), "call {g}: bound active");
        assert_eq!(flags & DEC_BOUND_INFEASIBLE != 0, e["energy_bound_infeasible"].as_bool().unwrap(), "call {g}: bound infeasible");
        let nc = calls[g].chunks;
        // Each vector against the largest of its kind in the call (fp32 tolerance relative
        // to the call's own scale: momentum sums over hundreds of nodes).
        for (name, chunk_key, imp_key, pick) in [
            ("v", "chunk_v", "imp_v", 0usize),
            ("w", "chunk_w", "imp_w", 1),
            ("dx", "chunk_dx", "imp_dx", 2),
            ("drot", "chunk_drot", "imp_drot", 3),
        ] {
            let mut want = f(&e[chunk_key]);
            want.extend(f(&e[imp_key]));
            let have: Vec<f64> = nodes_out
                .iter()
                .flat_map(|n| match pick {
                    0 => n.v,
                    1 => n.w,
                    2 => n.dx,
                    _ => n.drot,
                })
                .map(|x| x as f64)
                .collect();
            assert_eq!(want.len(), have.len());
            let scale = want.iter().fold(0.0f64, |a, x| a.max(x.abs())).max(1e-12);
            let worst = want.iter().zip(&have).map(|(a, b)| (a - b).abs()).fold(0.0, f64::max) / scale;
            assert!(worst < 2e-4, "call {g} ({nc} chunks) {name}: GPU and PyTorch differ by {worst:.2e} of the largest ({scale:.3e})");
        }
        let broke = i(&e["broke"]);
        let damage = f(&e["damage"]);
        for (k, (b, d)) in bonds_out.iter().enumerate() {
            assert_eq!(*b, broke[k] != 0, "call {g} bond {k}: break decision");
            assert!((*d as f64 - damage[k]).abs() < 1e-6, "call {g} bond {k}: damage {d} against {}", damage[k]);
        }
    }
}
